<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {useUserInfoStore} from '@/stores/userInfo'
import {catalogError,type AdminProduct} from '@/api/catalog'
import {imageDetail,uploadImage,removeImage,type ImageDetail,type ImageInput} from '@/api/images'
import {orderTime} from '@/api/orders'
import ProductCover from '@/views/shop/ProductCover.vue'
const props=defineProps<{product:AdminProduct;canEdit:boolean;disabled:boolean;refresh:()=>Promise<void>}>(),emit=defineEmits<{locked:[value:boolean]}>(),user=useUserInfoStore()
const detail=ref<ImageDetail>(),file=ref<File>(),alt=ref(''),busy=ref(false),error=ref(''),notice=ref(''),needsReload=ref(false),pending=ref<{action:'UPLOAD'|'REMOVE';input:ImageInput;file?:File}>(),fileInput=ref<HTMLInputElement>()
const has=(code:string)=>user.permissions.some(p=>p.code===code)
function pick(event:Event){const chosen=(event.target as HTMLInputElement).files?.[0];file.value=undefined;error.value='';if(!chosen)return;if(!['image/png','image/jpeg'].includes(chosen.type)||chosen.size>5242880||chosen.size===0){error.value='請選擇5MB以內的 PNG／JPEG 圖片。';(event.target as HTMLInputElement).value='';return}file.value=chosen}
async function load(){if(busy.value||props.disabled)return;busy.value=true;error.value='';try{detail.value=await imageDetail(props.product.id);if(needsReload.value){await props.refresh();needsReload.value=false}}catch(e){error.value=catalogError(e)}finally{busy.value=false;emit('locked',!!pending.value||needsReload.value)}}
async function submit(action?:'UPLOAD'|'REMOVE'){
 if(busy.value||props.disabled||needsReload.value)return
 if(!pending.value){if(!action||!props.canEdit||!detail.value?.enabled)return;if(action==='UPLOAD'&&(!file.value||!alt.value.trim()))return;if(!window.confirm(action==='UPLOAD'?'儲存這張商品主圖？原主圖會被替換。':'移除此商品主圖？舊圖片將排入清理。'))return;pending.value={action,input:{requestId:crypto.randomUUID(),expectedVersion:props.product.version,...(action==='UPLOAD'?{alt:alt.value.trim()}:{})},file:action==='UPLOAD'?file.value:undefined}}
 busy.value=true;emit('locked',true);error.value='';notice.value='';let acknowledged=false
 try{const op=pending.value;const r=op.action==='UPLOAD'?await uploadImage(props.product.id,op.input,op.file!):await removeImage(props.product.id,op.input);acknowledged=true;pending.value=undefined;detail.value=r.current;file.value=undefined;alt.value='';if(fileInput.value)fileInput.value.value='';notice.value=r.replayed?'已確認前次圖片操作，沒有重複新增。':'商品主圖已更新。';await props.refresh();detail.value=await imageDetail(props.product.id)}
 catch(e:any){if(acknowledged){needsReload.value=true;error.value='圖片操作已確認，讀取失敗，請重新核對。'}else if([400,401,403,404,409,413].includes(e.response?.status)){pending.value=undefined;needsReload.value=true;error.value=catalogError(e)}else{error.value='圖片操作回應未確認，請保留此頁，重試同一操作。'}}finally{busy.value=false;emit('locked',!!pending.value||needsReload.value)}
}
watch(()=>props.disabled,value=>{if(!value&&!detail.value&&!busy.value)load()})
onMounted(load)
</script>
<template><section class="image-panel" data-testid="image-panel"><h3>商品主圖</h3><p>每件商品提供一張主圖。PNG／JPEG、最大5MB、每邊4096像素；只能在草稿上傳、替換或移除。</p><p v-if="error" role="alert" class="alert alert-danger">{{ error }}</p><p v-if="notice" role="status" class="alert alert-success">{{ notice }}</p><button class="btn btn-outline-primary" :disabled="busy||disabled" @click="load">核對圖片</button><p v-if="detail&&!detail.enabled">此環境未啟用圖片儲存。</p><p v-if="!canEdit&&product.status==='DRAFT'">請先儲存或重新載入商品表單，再管理主圖。</p><div class="image-preview"><ProductCover :image="detail?.image" :category="product.category" /></div><p v-if="detail?.image">替代文字：{{ detail.image.alt }} · {{ detail.image.width }} × {{ detail.image.height }}</p>
<div v-if="pending||(detail?.enabled&&canEdit&&product.status==='DRAFT')"><template v-if="has('catalog.images.upload')"><label for="product-image-file">選擇商品主圖</label><input id="product-image-file" ref="fileInput" type="file" accept="image/png,image/jpeg" :disabled="busy||disabled||!!pending||needsReload" @change="pick"><label for="product-image-alt">圖片替代文字</label><input id="product-image-alt" v-model="alt" class="form-control" maxlength="160" :disabled="busy||disabled||!!pending||needsReload"></template><button v-if="pending" class="btn btn-primary" :disabled="busy||disabled||needsReload" @click="submit()">重試同一圖片操作</button><template v-else><button v-if="has('catalog.images.upload')" class="btn btn-primary" :disabled="busy||disabled||needsReload||!file||!alt.trim()" @click="submit('UPLOAD')">{{ detail?.image?'替換商品主圖':'上傳商品主圖' }}</button><button v-if="detail?.image&&has('catalog.images.remove')" class="btn btn-outline-danger" :disabled="busy||disabled||needsReload" @click="submit('REMOVE')">移除商品主圖</button></template></div>
<ol><li v-for="e in detail?.events" :key="e.requestId"><strong>{{ e.action==='UPLOAD'?'上傳／替換主圖':'移除主圖' }} · {{ e.actorUsername }}</strong><small>版本 {{ e.beforeVersion }} → {{ e.afterVersion }} · {{ orderTime(e.createdAt) }}</small><small>操作編號 {{ e.requestId }}</small></li></ol></section></template>
<style scoped>.image-panel{margin-top:28px;border-top:1px solid #ddd;padding-top:8px;overflow-wrap:anywhere}.image-preview{max-width:420px;margin:20px 0}.image-panel label{display:block;margin:12px 0 8px}.image-panel input[type=file]{width:100%}.image-panel button{margin:12px 12px 8px 0}.image-panel small{display:block;margin-top:5px}.image-panel li{margin-top:14px}.image-panel ol{padding-left:20px}</style>
